        #[arg(long = "all-targets", help = "Run the check for all targets instead of current only")]
        all_targets: bool,
        #[arg(long = "all-features", help = "Run the check for all features instead of the current active ones only")]
        all_features: bool,
    },
    #[command(about = "Remove artifacts from the target directory")]
    Clean,
    #[command(about = "Install or uninstall the toolchain")]
    Toolchain {
        #[command(subcommand)]
        command: Option<ToolchainCommands>,
    },
    #[command(about = "Generate shell completions")]
    Completions {
        #[arg(help = "The shell to generate completions for", value_enum)]
        shell: Shell,
    },
}

#[derive(Subcommand)]
enum ToolchainCommands {
    #[command(about = "Install the toolchain")]
    Install,
    #[command(about = "Uninstall the toolchain")]
    Uninstall,
}

