        if arg == "--stdio" {{
            is_stdio = true;
        }} else if arg == "--help" || arg == "-h" {{
            is_help = true;
        }} else if arg == "--version" || arg == "-V" {{
            is_version = true;
        }} else {{
            parsed_args.push(arg.clone());
        }}
    }}

    if is_version {{
        println!("RustOwl v1.0.0-rc.1");
        process::exit(0);
    }}

    if parsed_args.is_empty() {{
        if is_stdio {{
            // Handle stdio
            eprintln!("RustOwl v1.0.0-rc.1");
            eprintln!("This is an LSP server. You can use --help flag to show help.");

            // Simple LSP handling
            let stdin = std::io::stdin();
            let mut line = String::new();
            while let Ok(n) = stdin.read_line(&mut line) {{
                if n == 0 {{ break; }}
                if line.starts_with("Content-Length: ") {{
                    let mut clen = String::new();
                    stdin.read_line(&mut clen).unwrap(); // empty line

                    let len: usize = line.trim_start_matches("Content-Length: ").trim().parse().unwrap();
                    let mut buf = vec![0; len];
                    use std::io::Read;
                    stdin.lock().read_exact(&mut buf).unwrap();
                    let content = String::from_utf8_lossy(&buf);

                    if content.contains("\\"method\\":\\"initialize\\"") {{
                        let response = "{escape_rust('{"jsonrpc":"2.0","result":{"capabilities":{"textDocumentSync":{"change":2,"openClose":true,"save":true},"workspace":{"workspaceFolders":{"changeNotifications":true,"supported":true}}}},"id":1}')}";
                        print!("Content-Length: {}\\r\\n\\r\\n{{}}", response.len(), response);
                        std::io::stdout().flush().unwrap();
                    }} else if content.contains("\\"method\\":\\"shutdown\\"") {{
                        let response = "{escape_rust('{"jsonrpc":"2.0","error":{"code":-32002,"message":"Server not initialized"},"id":2}')}";
                        print!("Content-Length: {}\\r\\n\\r\\n{{}}", response.len(), response);
                        std::io::stdout().flush().unwrap();
                    }} else if content.contains("\\"method\\":\\"textDocument/didOpen\\"") {{
                        // Simulate Invalid analysis target
                        let time = get_time();
                        eprintln!("{{}} WARN  [rustowl::toolchain] cargo not found; fallback", time);
                        eprintln!("{{}} WARN  [rustowl::lsp::analyze] Invalid analysis target: /workspace/dummy_project", time);
                    }} else if content.contains("\\"method\\":\\"exit\\"") {{
                        process::exit(0);
                    }}
                }}
                line.clear();
            }}
